package android.app;import java.util.*;public class NotificationManager {public static final int IMPORTANCE_LOW=2,IMPORTANCE_NONE=0;public boolean allowed=true;public Map<String,NotificationChannel> channels=new HashMap<>();public Map<Integer,Notification> cards=new HashMap<>();public void createNotificationChannel(NotificationChannel c){channels.putIfAbsent(c.id,c);}public NotificationChannel getNotificationChannel(String s){return channels.get(s);}public boolean areNotificationsEnabled(){return allowed;}public void cancel(int id){cards.remove(id);}public void notify(int id,Notification n){cards.put(id,n);}}